    if(selected&&!current()){loadAbort&&loadAbort.abort();selectionGeneration++;lastChat='';$('messages').replaceChildren();$('notice').hidden=false;$('notice').textContent='此会话已归档或绑定已失效';$('composer').hidden=true;return;}
